	uid, err := parseUUID(workspaceID)
	if err != nil {
		return Workspace{}, err
	}

	accessible, hasAuth := ScopedWorkspaceIDs(ctx)
	if hasAuth && len(accessible) == 0 {
		return Workspace{}, ErrNotFound
	}

	var (
		q    string
		args []interface{}
	)
	if hasAuth {
		q = `
		SELECT id, organization_id, slug, name, management_repo_id, branch_pattern, created_at, updated_at
		FROM workspaces WHERE id = $1 AND id = ANY($2)`
		args = []interface{}{uid, accessible}
	} else {
		q = `
		SELECT id, organization_id, slug, name, management_repo_id, branch_pattern, created_at, updated_at
		FROM workspaces WHERE id = $1`
		args = []interface{}{uid}
	}

	row := r.db.QueryRow(ctx, q, args...)
	var w Workspace
	if err := row.Scan(&w.ID, &w.OrganizationID, &w.Slug, &w.Name, &w.ManagementRepoID, &w.BranchPattern, &w.CreatedAt, &w.UpdatedAt); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return Workspace{}, ErrNotFound
		}
		return Workspace{}, err
	}
	return w, nil
}

